#!/usr/bin/env python3
from pathlib import Path
import runpy,re

# v0.83: diagnostic-only fingerprint reconstruction probe.
# Preserve v0.82 semantic Resource admission and calibrated actuator setup, but
# never actuate ChatGPT in this build. Capture only sanitized hash/length/count
# deltas between admission and final pre-effect re-certification.
runpy.run_path("ci/generate_chatgpt_webview_v84_resource_semantic_turn_identity.py", run_name="__main__")

ROOT=Path("runtime_probes/chatgpt-webview-stable-probe")
PKG=ROOT/"app/src/main/java/com/homayounisaghar/chatgptwebviewprobe"
OLD=PKG/"OrchestratorResourceToolsV84Activity.java"
ACT=PKG/"OrchestratorResourceToolsV85Activity.java"
s=OLD.read_text()

def method(name,body,rettype="void"):
    global s
    pat=rf'    private {re.escape(rettype)} {re.escape(name)}\([^\n]*\)\{{.*?\n    \}}\n\n'
    m=re.search(pat,s,re.S)
    assert m,(rettype,name,"method not found")
    s=s[:m.start()]+body+s[m.end():]

def replace_once(old,new,label):
    global s
    n=s.count(old)
    assert n==1,(label,n)
    s=s.replace(old,new,1)

s=s.replace("OrchestratorResourceToolsV84Activity","OrchestratorResourceToolsV85Activity")
s=s.replace("TelemetryConfigV84","TelemetryConfigV85")
s=s.replace("isResourceLifecycleV84","isResourceLifecycleV85")
s=s.replace("isResourceTerminalV84","isResourceTerminalV85")
s=s.replace("armResourceReceiptDeadlineV84","armResourceReceiptDeadlineV85")
s=s.replace("resourceV84ClaimTurnFingerprint","resourceV85ClaimTurnFingerprint")
s=s.replace('SCHEMA="cp-v84-resource-semantic-turn-identity-v1"','SCHEMA="cp-v85-resource-fingerprint-drift-probe-v1"')
s=s.replace('SCENARIO="resource-semantic-turn-identity-calibrated-actuator"','SCENARIO="resource-fingerprint-component-drift-probe"')
s=s.replace('getSharedPreferences("cp_v84_resource_semantic_turn_identity",MODE_PRIVATE)','getSharedPreferences("cp_v85_resource_fingerprint_drift_probe",MODE_PRIVATE)')
s=s.replace('testId="cp82-"+UUID.randomUUID();','testId="cp83-"+UUID.randomUUID();')
s=s.replace('"resource_v84_','"resource_v85_')
s=s.replace('"resource-v84-','"resource-v85-')
s=s.replace('v0.82 Semantic turn identity Resource acceptance ready.','v0.83 Fingerprint drift diagnostic ready.')

# Add diagnostic claim components. These are hashes/lengths only; raw text stays local.
m=re.search(r'(\n\s*private String resourceV85ClaimTurnFingerprint[^;]*;)',s)
assert m,"claim fingerprint field"
extra='''\n    private String resourceV85ClaimAssistantHash="-",resourceV85ClaimUserHash="-";\n    private String resourceV85ClaimAssistantProjectionHash="-",resourceV85ClaimUserProjectionHash="-";\n    private int resourceV85ClaimAssistantLen=-1,resourceV85ClaimUserLen=-1;\n    private int resourceV85ClaimAssistantProjectionLen=-1,resourceV85ClaimUserProjectionLen=-1;\n    private int resourceV85ClaimAssistantOrdinal=-1,resourceV85ClaimAssistantTurnCount=-1,resourceV85ClaimUserTurnCount=-1;\n    private boolean resourceV85DiagnosticOnly(){return true;}'''
s=s[:m.end()]+extra+s[m.end():]

# Ensure new diagnostic fields are reset wherever the claim fingerprint is reset.
reset='resourceV85ClaimTurnFingerprint="-";'
reset_new='resourceV85ClaimTurnFingerprint="-";resourceV85ClaimAssistantHash="-";resourceV85ClaimUserHash="-";resourceV85ClaimAssistantProjectionHash="-";resourceV85ClaimUserProjectionHash="-";resourceV85ClaimAssistantLen=-1;resourceV85ClaimUserLen=-1;resourceV85ClaimAssistantProjectionLen=-1;resourceV85ClaimUserProjectionLen=-1;resourceV85ClaimAssistantOrdinal=-1;resourceV85ClaimAssistantTurnCount=-1;resourceV85ClaimUserTurnCount=-1;'
assert s.count(reset)>=2,s.count(reset)
s=s.replace(reset,reset_new)

